  /// Samples per second.
  @ffi.Uint32()
  external int sample_rate;

  /// One of the `ANYCODEC_CHANNEL_LAYOUT_*` constants.
  @ffi.Uint32()
  external int channels;

  /// Number of sample frames (one per channel).
  @ffi.Uint32()
  external int frames;

  /// Presentation timestamp in the stream timebase.
  @ffi.Int64()
  external int pts;

  /// Interleaved sample bytes.
  external ffi.Pointer<ffi.UnsignedChar> data;

  /// Length of `data` in bytes.
  @ffi.UintPtr()
  external int len;

  static ffi.Pointer<AnyCodecAudioFrame> $allocate(
    ffi.Allocator $allocator, {
    required int sample_format,
    required int sample_rate,
    required int channels,
    required int frames,
    required int pts,
    required ffi.Pointer<ffi.UnsignedChar> data,
    required int len,
  }) => $allocator<AnyCodecAudioFrame>()
    ..ref.sample_format = sample_format
    ..ref.sample_rate = sample_rate
    ..ref.channels = channels
    ..ref.frames = frames
    ..ref.pts = pts
    ..ref.data = data
    ..ref.len = len;
}

