/// An owned byte buffer.
final class AnyCodecBuffer extends ffi.Opaque {}

/// What is available for one codec in one direction.
final class AnyCodecCapability extends ffi.Struct {
  /// One of the `ANYCODEC_CODEC_*` constants.
  @ffi.Uint32()
  external int codec;

  /// `0` for encoders, `1` for decoders.
  @ffi.Uint32()
  external int kind;

  /// Bitmask of every backend registered for this codec, available or not.
  @ffi.Uint32()
  external int backends;

  /// Bitmask of the backends that can actually run right now.
  @ffi.Uint32()
  external int available_backends;

  /// `1` when at least one available backend is known to use dedicated hardware.
  @ffi.Uint32()
  external int hardware;

  /// `1` when at least one available backend is a software fallback.
  @ffi.Uint32()
  external int software;

  static ffi.Pointer<AnyCodecCapability> $allocate(
    ffi.Allocator $allocator, {
    required int codec,
    required int kind,
    required int backends,
    required int available_backends,
    required int hardware,
    required int software,
  }) => $allocator<AnyCodecCapability>()
    ..ref.codec = codec
    ..ref.kind = kind
    ..ref.backends = backends
    ..ref.available_backends = available_backends
    ..ref.hardware = hardware
    ..ref.software = software;
}

/// How a live encoder or decoder is doing its work.
///
/// This is the single struct a caller needs in order to know whether an operation
/// landed on a software fallback: check [`is_software`](Self::is_software) or
/// compare `implementation` against `ANYCODEC_IMPLEMENTATION_SOFTWARE`.
final class AnyCodecCodecPath extends ffi.Struct {
  /// One of the `ANYCODEC_BACKEND_*` constants.
  @ffi.Uint32()
  external int backend;

  /// `ANYCODEC_IMPLEMENTATION_NATIVE` or `ANYCODEC_IMPLEMENTATION_SOFTWARE`.
  @ffi.Uint32()
  external int implementation;

  /// `1` only when the backend is known to run on dedicated hardware.
  @ffi.Uint32()
  external int hardware_accelerated;

  /// `1` when a software fallback is doing the work.
  @ffi.Uint32()
  external int is_software;

  /// The concrete object in use, e.g. `"VTCompressionSession h264"`.
  @ffi.Array.multi([256])
  external ffi.Array<ffi.Char> detail;

  /// Why a higher-priority backend was skipped. Empty when nothing was skipped.
  @ffi.Array.multi([512])
  external ffi.Array<ffi.Char> fallback_reason;
}

