/// A live encoder session.
///
/// `pending` buffers whatever `Encoder::flush` produced so that the C-side drain
/// loop (`anycodec_encoder_receive`) can deliver it in order: the trait returns
/// the tail synchronously, while the C ABI is pull-only.
final class AnyCodecEncoder extends ffi.Opaque {}

/// Everything needed to start an encoder, flattened for C.
final class AnyCodecEncoderConfig extends ffi.Struct {
  /// One of the `ANYCODEC_CODEC_*` constants.
  @ffi.Uint32()
  external int codec;

  /// Luma width in pixels; ignored for audio codecs.
  @ffi.Uint32()
  external int width;

  /// Luma height in pixels; ignored for audio codecs.
  @ffi.Uint32()
  external int height;

  /// One of the `ANYCODEC_PIXEL_FORMAT_*` constants.
  @ffi.Uint32()
  external int pixel_format;

  /// Frames per second numerator.
  @ffi.Uint32()
  external int framerate_num;

  /// Frames per second denominator.
  @ffi.Uint32()
  external int framerate_den;

  /// Target keyframe distance in frames; `0` lets the backend choose.
  @ffi.Uint32()
  external int keyframe_interval;

  /// Samples per second; ignored for video codecs.
  @ffi.Uint32()
  external int sample_rate;

  /// One of the `ANYCODEC_CHANNEL_LAYOUT_*` constants.
  @ffi.Uint32()
  external int channels;

  /// One of the `ANYCODEC_SAMPLE_FORMAT_*` constants.
  @ffi.Uint32()
  external int sample_format;

  /// Requested encoded frame length in milliseconds; `0` lets the backend choose.
  @ffi.Uint32()
  external int frame_duration_ms;

  /// Target bitrate in bits per second; `0` means "use `quality`".
  @ffi.Uint64()
  external int bitrate;

  /// Quality hint in `0.0..=1.0`, or `0.0` for unset.
  @ffi.Float()
  external double quality;

  /// One of the `ANYCODEC_PRESET_*` constants.
  @ffi.Uint32()
  external int preset;

  /// Number of entries in `option_keys`/`option_values`.
  @ffi.Uint32()
  external int option_count;

  /// Backend-specific option names; may be NULL when `option_count` is `0`.
  external ffi.Pointer<ffi.Pointer<ffi.Char>> option_keys;

  /// Backend-specific option values; may be NULL when `option_count` is `0`.
  external ffi.Pointer<ffi.Pointer<ffi.Char>> option_values;

