    required int keyframe_interval,
    required int sample_rate,
    required int channels,
    required int sample_format,
    required int frame_duration_ms,
    required int bitrate,
    required double quality,
    required int preset,
    required int option_count,
    required ffi.Pointer<ffi.Pointer<ffi.Char>> option_keys,
    required ffi.Pointer<ffi.Pointer<ffi.Char>> option_values,
  }) => $allocator<AnyCodecEncoderConfig>()
    ..ref.codec = codec
    ..ref.width = width
    ..ref.height = height
    ..ref.pixel_format = pixel_format
    ..ref.framerate_num = framerate_num
    ..ref.framerate_den = framerate_den
    ..ref.keyframe_interval = keyframe_interval
    ..ref.sample_rate = sample_rate
    ..ref.channels = channels
    ..ref.sample_format = sample_format
    ..ref.frame_duration_ms = frame_duration_ms
